function header() {
  return `<header class="site-header container"><a class="brand" href="/" aria-label="C M Nafi home">${star}<span>C M Nafi<span class="brand-dot">.</span></span></a><nav aria-label="Main navigation"><a href="/" ${page==='home'?'aria-current="page"':''}>Journal</a><a href="/era/" ${page==='era'?'aria-current="page"':''}>Era<span class="nav-dot"></span></a><a href="/bookmarks/" ${page==='bookmarks'?'aria-current="page"':''}>Bookmarks</a><a href="https://www.cmnafi.com/story/">About</a></nav><div class="header-actions"><button class="theme-button icon-button" aria-label="Switch to ${theme==='light'?'dark':'light'} theme">${theme==='light'?icons.moon:icons.sun}</button><a href="mailto:nafi@cmnafi.com" class="contact-link">Say hello ${icons.external}</a></div></header>`;
}
function footer() {
  return `<footer class="container site-footer"><div class="footer-top"><div><div class="footer-wordmark">Stay curious<span>.</span></div><p>A little writing. A little building. Always learning.</p></div><a href="mailto:nafi@cmnafi.com" class="footer-email">nafi@cmnafi.com ${icons.external}</a></div><div class="footer-bottom"><span>© 2026 C M Nafi</span><span class="footer-place"><span class="status-dot"></span> Made with intention, in Tampa.</span><div><a href="https://github.com/CMNafi" target="_blank" rel="noopener noreferrer">GitHub ${icons.external}</a><a href="https://www.linkedin.com/in/cm-nafi" target="_blank" rel="noopener noreferrer">LinkedIn ${icons.external}</a></div></div></footer>`;
}
function chips(values, type='category') {
  return values.map(value=>`<button class="chip ${state.category===value?'active':''}" data-${type}="${safe(value)}" aria-pressed="${state.category===value}">${safe(value)}${page==='era'&&['All','Projects','Ideas','Companies'].includes(value)?`<span>${value==='All'?projects.length:projects.filter(p=>p.kind===value).length}</span>`:''}</button>`).join('');
}
function articleRows() {
  const list = articles.filter(a=>state.category==='All'||a.category===state.category);
  return list.map((a,i)=>`<a class="article-row" href="${a.url}"><span class="article-index">0${i+1}</span><div class="article-copy"><div class="eyebrow article-meta">${a.category}<span> / </span>${a.date}</div><h3>${a.title}</h3><p>${a.description}</p></div><span class="article-time">${a.time}</span><span class="round-arrow">${icons.external}</span></a>`).join('');
}
function home() {
  return `<main id="main" class="container"><section class="home-hero"><div class="hero-main"><div class="eyebrow"><span class="status-dot"></span> THE PERSONAL HOME OF C M NAFI</div><h1>Curiosity,<br>put to <em>work.</em><span class="hero-asterisk">${star}</span></h1></div><div class="hero-bio"><span class="tiny-line"></span><p>I’m Nafi — a solutions engineer exploring the intersection of <strong>finance, technology, and everything in between.</strong></p><p class="muted">This is where I think out loud, build things, and collect what catches my eye.</p><a class="text-link" href="https://www.cmnafi.com/story/">A little more about me ${icons.arrow}</a></div></section><section class="featured-writing" aria-labelledby="featured-title"><div class="featured-image"><img src="/assets/capital-orbits.svg" alt="Abstract orbital illustration of capital moving through a system"><div class="image-top"><span>FIELD NOTES / 001</span><span>CAPITAL, IN MOTION</span></div><span class="image-bottom">THE COST OF GOING SOMEWHERE.</span></div><div class="featured-copy"><div class="eyebrow"><span class="small-label">LATEST ESSAY</span><span>FINANCE / VENTURE CAPITAL</span></div><h2 id="featured-title">Uber: The $32.8<br>Billion Hole</h2><p>More outside capital than any startup before it. A $32.8 billion hole. The full funding history, round by round.</p><div class="reading-meta">October 10, 2026<span>·</span>20 min read</div><a class="solid-link" href="https://www.cmnafi.com/field-notes/uber-the-32-billion-hole/">Read the essay ${icons.arrow}</a></div></section><section class="writing-section"><div class="section-heading"><div><div class="eyebrow">NOTES FROM THE INTERSECTION</div><h2>Recent writing<span class="accent">.</span></h2></div><a href="https://www.cmnafi.com/field-notes/" class="text-link">All field notes ${icons.arrow}</a></div><div class="writing-filters" role="group" aria-label="Filter writing">${chips(['All','Finance','Books','Cricket'])}</div><div id="article-rows">${articleRows()}</div></section><section class="explore-section"><a class="explore-block era-block" href="/era/"><div class="eyebrow">01 / THE THINGS I BUILD</div><div class="explore-title">Enter <em>era</em><span>${icons.external}</span></div><p>Projects, businesses, and ideas.<br>A home for everything taking shape.</p><div class="explore-bottom"><span>EXPLORE THE WORK</span>${star}</div></a><a class="explore-block bookmarks-block" href="/bookmarks/"><div class="eyebrow">02 / THE THINGS I FIND</div><div class="explore-title">The good <em>stuff.</em><span>${icons.external}</span></div><p>Open-source tools worth a closer look.<br>A growing shelf of useful discoveries.</p><div class="explore-bottom"><span>OPEN THE BOOKMARKS</span>${icons.bookmark}</div></a></section></main>`;
}
function projectArt(p) {
  if(['worldview','regulatory'].includes(p.art)) return `<img src="/assets/${p.art}.svg" alt="" loading="lazy">`;
  if(['cup','cricket','playbook'].includes(p.art)) return `<div class="pitch-graphic"><div class="pitch-ring outer"></div><div class="pitch-ring inner"></div><div class="pitch-line"></div><span class="pitch-point p1"></span><span class="pitch-point p2"></span><span class="pitch-point p3"></span><span class="pitch-point p4"></span><span class="pitch-point p5"></span><span class="pitch-center">${p.art==='cup'?'26':'XI'}</span></div>`;
  if(p.art==='caia') return '<div class="caia-graphic"><span>α</span><div class="caia-line l1"></div><div class="caia-line l2"></div><div class="caia-line l3"></div><div class="caia-line l4"></div><div class="caia-line l5"></div></div>';
  if(['screener','manager'].includes(p.art)) return '<div class="data-graphic"><div></div><div></div><div></div><div></div><div></div><div></div><span>IN DEVELOPMENT ↗</span></div>';
  return `<div class="idea-graphic">${p.art==='homepage'?'<span>N.</span>':star}<span class="idea-orbit"></span></div>`;
}
function projectCards() {
  const query = state.query.toLowerCase();
  const list = projects.filter(p=>(state.category==='All'||p.kind===state.category||p.status===state.category) && `${p.name} ${p.description} ${p.category}`.toLowerCase().includes(query));
  if(!list.length) return `<div class="empty-state"><span class="empty-mark">${star}</span><h3>${state.category==='Companies'?'Room for the next chapter.':'Nothing here just yet.'}</h3><p>${state.category==='Companies'?'Companies and businesses will live here as the collection grows. For now, explore the projects and ideas already taking shape.':'Try another search or explore a different category.'}</p><button class="outline-button" data-reset>Explore all work ${icons.arrow}</button></div>`;
  return list.map((p,i)=>`<article class="project-card"><a class="project-art art-${p.art}" href="${p.url}" target="_blank" rel="noopener noreferrer" aria-label="Explore ${p.name}">${projectArt(p)}<div class="art-top"><span>${p.category.toUpperCase()}</span><span class="project-number">${String(projects.indexOf(p)+1).padStart(2,'0')}</span></div><div class="art-bottom"><span>${p.label}</span><span class="art-arrow">${icons.external}</span></div></a><div class="project-body"><div class="project-category"><span>${p.tag}</span><span class="project-status ${p.status.toLowerCase()}"><span class="status-dot"></span>${p.status}</span></div><h3><a href="${p.url}" target="_blank" rel="noopener noreferrer">${p.name}</a></h3><p>${p.description}</p><a class="project-link" href="${p.url}" target="_blank" rel="noopener noreferrer">${p.status==='Live'?'Explore project':'See the idea'} ${icons.external}</a></div></article>`).join('');
}
function era() {
  return `<main id="main" class="container"><section class="subpage-hero era-hero"><div><div class="eyebrow"><span class="status-dot"></span> AN INDEPENDENT CHAPTER</div><h1 class="era-word">era<span>${star}</span><span class="era-period">.</span></h1></div><div class="subpage-intro"><h2>Ideas become things.<br>Things become <em>possibilities.</em></h2><p>A place for my companies, projects, and experiments. Some out in the world. Some still on the back of a napkin. All part of the same story.</p><div class="era-stats"><span><b>10</b> things taking shape</span><span><i class="status-dot"></i> 6 live · 4 brewing</span></div></div></section><div class="collection-toolbar"><div class="collection-tabs" role="group" aria-label="Filter Era projects">${chips(['All','Companies','Projects','Ideas'])}</div><label class="search-field">${icons.search}<input id="collection-search" type="search" placeholder="Find something…" aria-label="Search projects"></label></div><div class="collection-caption"><span>THE COLLECTION</span><span id="era-result-count">10 PROJECTS & IDEAS</span></div><section id="project-grid" class="project-grid" aria-label="Era project collection">${projectCards()}</section><section class="closing-note"><span class="handwritten-star">${star}</span><div><h2>The next thing starts with a conversation.</h2><p>Have an idea, a question, or a problem worth solving? I’d love to hear it.</p></div><a class="outline-button" href="mailto:nafi@cmnafi.com">Let’s talk ${icons.external}</a></section></main>`;
}
function projectLogo(b,small=false) {
  return `<span class="tool-logo logo-${b.id} ${small?'small':''}" style="--logo-bg:${b.color};--logo-ink:${b.ink}" aria-hidden="true">${b.mark}</span>`;
}
function bookmarkCards() {
  const query = state.query.toLowerCase();
  const list = bookmarks.filter(b=>(state.category==='All'||b.category===state.category) && (!state.savedOnly||saved.has(b.id)) && `${b.name} ${b.description} ${b.category} ${b.repo} ${b.license}`.toLowerCase().includes(query));
  if(!list.length) return `<div class="empty-state"><span class="empty-mark">${icons.bookmark}</span><h3>${state.savedOnly?'Your shelf is waiting.':'No matching discoveries.'}</h3><p>${state.savedOnly?'Tap the bookmark icon on any project to save it to this browser.':'Try a different keyword or choose another category.'}</p><button class="outline-button" data-reset>Explore all bookmarks ${icons.arrow}</button></div>`;
  return list.map(b=>`<article class="bookmark-card"><div class="bookmark-card-top">${projectLogo(b)}<button class="save-button icon-button ${saved.has(b.id)?'is-saved':''}" data-save="${b.id}" aria-pressed="${saved.has(b.id)}" aria-label="${saved.has(b.id)?'Unsave':'Save'} ${b.name}">${icons.bookmark}</button></div><div class="bookmark-card-body"><div class="bookmark-category">${b.category}${b.featured?'<span class="featured-dot" title="Collection highlight">✦</span>':''}</div><h3><a href="${b.home}" target="_blank" rel="noopener noreferrer">${b.name}</a></h3><p>${b.description}</p></div><div class="bookmark-card-footer"><a href="https://github.com/${b.repo}" target="_blank" rel="noopener noreferrer" aria-label="View ${b.name} on GitHub">${icons.github}<span>GitHub</span>${icons.external}</a><span class="license" ${b.licenseNote?`title="${safe(b.licenseNote)}"`:''}>${b.license}</span></div>${b.licenseNote?`<p class="license-note">${b.licenseNote}</p>`:''}</article>`).join('');
}
function bookmarksPage() {
  return `<main id="main" class="container"><section class="subpage-hero bookmarks-hero"><div><div class="eyebrow"><span class="status-dot"></span> GOOD THINGS, KEPT CLOSE</div><h1>Book<em>marks</em><span class="bookmark-hero-symbol">${icons.bookmark}</span><span class="accent">.</span></h1><p class="hero-description">The internet is full of good work.<br>Here’s a little shelf for the tools worth finding.</p></div><aside class="bookmark-hero-note"><div class="stacked-logos">${projectLogo(bookmarks[0],true)}${projectLogo(bookmarks[1],true)}${projectLogo(bookmarks[2],true)}</div><p>Open code.<br>Endless possibilities.</p><span>12 PROJECTS TO EXPLORE ${icons.external}</span></aside></section><div class="bookmarks-subheading"><div class="eyebrow">THE OPEN-SOURCE SHELF</div><p>Independent tools. Shared knowledge. A good place to start building.</p></div><div class="bookmarks-search-row"><label class="search-field large-search">${icons.search}<input id="collection-search" type="search" placeholder="Search projects, tools, or a little inspiration…" aria-label="Search bookmarks"><kbd>/</kbd></label><button id="saved-filter" class="saved-filter" aria-pressed="false">${icons.bookmark}My shelf <span id="saved-count">${saved.size}</span></button></div><div class="bookmark-toolbar"><div class="collection-tabs" role="group" aria-label="Filter bookmarks">${chips(['All','Engineering','Data','AI','Finance','Productivity','Self-hosting','Automation'])}</div><div class="view-controls" role="group" aria-label="Collection view"><button class="icon-button ${state.view==='grid'?'active':''}" data-view="grid" aria-label="Grid view" aria-pressed="${state.view==='grid'}">${icons.grid}</button><button class="icon-button ${state.view==='list'?'active':''}" data-view="list" aria-label="List view" aria-pressed="${state.view==='list'}">${icons.list}</button></div></div><div class="collection-caption"><span id="bookmark-result-count">12 DISCOVERIES</span><span>CURATED, NOT RANKED</span></div><section id="bookmark-grid" class="bookmark-grid ${state.view==='list'?'list-view':''}" aria-label="Open-source project collection">${bookmarkCards()}</section><section class="bookmark-note"><span>${icons.github}</span><div><h3>Good tools are made by good communities.</h3><p>These are a curated starting point, not a live popularity ranking. Explore the code, check each license, and support the people building it.</p></div><a class="text-link" href="mailto:nafi@cmnafi.com?subject=A%20bookmark%20for%20your%20shelf">Suggest a bookmark ${icons.arrow}</a></section></main>`;
}

document.title = page==='era'?'Era — The things taking shape · C M Nafi':page==='bookmarks'?'Bookmarks — The open-source shelf · C M Nafi':'C M Nafi — Curiosity, put to work.';
document.getElementById('app').innerHTML = header() + (page==='era'?era():page==='bookmarks'?bookmarksPage():home()) + footer() + '<div id="live-announcement" class="sr-only" aria-live="polite" role="status"></div>';
function announce(message) { document.getElementById('live-announcement').textContent=message; }
function refreshCollection() {
  if(page==='home') { document.getElementById('article-rows').innerHTML=articleRows(); return; }
  const query = state.query.toLowerCase();
  if(page==='era') {
    document.getElementById('project-grid').innerHTML=projectCards();
    const count=projects.filter(p=>(state.category==='All'||p.kind===state.category||p.status===state.category)&&`${p.name} ${p.description} ${p.category}`.toLowerCase().includes(query)).length;
    document.getElementById('era-result-count').textContent=`${count} ${count===1?'PROJECT OR IDEA':'PROJECTS & IDEAS'}`;
    announce(`${count} projects and ideas shown`);
  } else {
    const grid=document.getElementById('bookmark-grid');
    grid.innerHTML=bookmarkCards();
    grid.classList.toggle('list-view',state.view==='list');
    const count=bookmarks.filter(b=>(state.category==='All'||b.category===state.category)&&(!state.savedOnly||saved.has(b.id))&&`${b.name} ${b.description} ${b.category} ${b.repo} ${b.license}`.toLowerCase().includes(query)).length;
    document.getElementById('bookmark-result-count').textContent=`${count} ${count===1?'DISCOVERY':'DISCOVERIES'}`;
    document.getElementById('saved-count').textContent=saved.size;
    document.getElementById('saved-filter').classList.toggle('active',state.savedOnly);
    document.getElementById('saved-filter').setAttribute('aria-pressed',String(state.savedOnly));
    announce(`${count} bookmarks shown`);
  }
}
document.addEventListener('click',e=>{
  const category=e.target.closest('[data-category]');
  if(category) { state.category=category.dataset.category; document.querySelectorAll('[data-category]').forEach(b=>{const selected=b.dataset.category===state.category;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',String(selected));});refreshCollection(); }
  const save=e.target.closest('[data-save]');
  if(save) { const id=save.dataset.save;saved.has(id)?saved.delete(id):saved.add(id);savePreference('cmnafi-bookmarks',[...saved]);refreshCollection();document.querySelector(`[data-save="${id}"]`)?.focus(); }
  if(e.target.closest('#saved-filter')) {state.savedOnly=!state.savedOnly;refreshCollection();}
  const view=e.target.closest('[data-view]');
  if(view) {state.view=view.dataset.view;savePreference('cmnafi-bookmark-view',state.view);document.querySelectorAll('[data-view]').forEach(b=>{const selected=b.dataset.view===state.view;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',String(selected));});refreshCollection();}
  if(e.target.closest('[data-reset]')) {state.category='All';state.query='';state.savedOnly=false;const input=document.getElementById('collection-search');if(input)input.value='';document.querySelectorAll('[data-category]').forEach(b=>{const selected=b.dataset.category==='All';b.classList.toggle('active',selected);b.setAttribute('aria-pressed',String(selected));});refreshCollection();}
  const themeButton=e.target.closest('.theme-button');
  if(themeButton) {theme=theme==='light'?'dark':'light';document.documentElement.dataset.theme=theme;savePreference('cmnafi-theme',theme);themeButton.innerHTML=theme==='light'?icons.moon:icons.sun;themeButton.setAttribute('aria-label',`Switch to ${theme==='light'?'dark':'light'} theme`);}
});
document.getElementById('collection-search')?.addEventListener('input',e=>{state.query=e.target.value.trim();refreshCollection();});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){const search=document.getElementById('collection-search');if(search){e.preventDefault();search.focus();}}});
